ad del proveedor está acreditada y autorización explícita aplicable registrada. No asumir recurrencia, no solicitar tarjeta adicional cuando Yape manual elegible, no mostrar nombre/logo proveedor; solo logo Yape. Binding runtime pendiente; no modifica IG ni fuentes oficiales.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/286","solicitante":"Cristhian / Claude S22-AY"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"ay_yape_collection"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"ay_yape_regular_denied_despite_eligible"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"ay_yape_recurring_without_evidence"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_manual_missing_phone_or_code"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_manual_without_confirmation"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_manual_reminder_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_reminder_not_customer_config"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_autodebit_consent_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ay_yape_provider_brand_in_collection"},"der":{"lit":true}}}},"pruebas":[{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":false,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":true,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"