y_yape_collection":true,"ay_yape_regular_denied_despite_eligible":false,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":true,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":false,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":true,"ay_yape_provider_brand_in_collection":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_collection":true,"ay_yape_regular_denied_despite_eligible":false,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":true},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ay_yape_collection":false,"ay_yape_regular_denied_despite_eligible":true,"ay_yape_recurring_without_evidence":false,"ay_yape_manual_missing_phone_or_code":false,"ay_yape_manual_without_confirmation":false,"ay_yape_manual_reminder_missing":false,"ay_yape_reminder_not_customer_config":false,"ay_yape_autodebit_consent_missing":false,"ay_yape_provider_brand_in_collection":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"}]}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; hashes jsonb:='{}'; hash_all text; t record; v integer;
BEGIN
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo'; v:=(p->>'version_nucleo')::int;
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM v THEN RAISE EXCEPTION 'S22AY_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 h:=lf_ops.nucleo_hash_paquete_v1(cd,v); hashes:=hashes||jsonb_build_object(cd,h);
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=v LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22AY_VECTOR_FAIL %',cd; END IF;
 END LOOP;
 END LOOP;
 SELECT string_agg(j.key||'='||j.value,',' ORDER BY j.key) INTO hash_all FROM jsonb_each_text(hashes) j;
 RAISE EXCEPTION 'S22AY_HASH_ALL %',hash_all;
END $ay$;
COMMIT;
